const b = $input.first().json.body || {};
const p = b.pipeline || {};
const tp = p.trigger_parameters || {};
const git = tp.git || {};
const gl = tp.gitlab || {};
const wf = b.workflow || {};
const job = b.job || {};

const isJob = b.type === 'job-completed';
const status = (isJob ? job.status : wf.status) || 'unknown';
const name = isJob ? `job ${job.name}` : `workflow ${wf.name}`;
const url = (isJob ? job.url : wf.url) || p.url || '';

const colors = { success: 'green', failed: 'red', error: 'red', canceled: 'grey', unauthorized: 'orange', on_hold: 'orange' };
const icons = { success: '✅', failed: '❌', error: '❌', canceled: '⚪', unauthorized: '🔒', on_hold: '⏸️' };

const project = (b.project && b.project.name) || gl.repo_name || 'Project';
const ref = git.tag ? `tag \`${git.tag}\`` : `branch \`${git.branch || gl.branch || '-'}\``;
const sha = (git.checkout_sha || gl.commit_sha || '').slice(0, 8);
const author = gl.commit_author_name || gl.user_name || '-';
const title = gl.commit_title || '';

const start = new Date(wf.created_at || job.started_at || 0);
const stop = new Date(wf.stopped_at || job.stopped_at || b.happened_at || 0);
const secs = Math.max(0, Math.round((stop - start) / 1000));
const dur = secs >= 60 ? `${Math.floor(secs / 60)}m ${secs % 60}s` : `${secs}s`;

const content = [
  `**Project:** ${project}`,
  `**Ref:** ${ref}  (${sha})`,
  `**Pipeline:** #${p.number ?? '-'}`,
  `**Duration:** ${dur}`,
  `**Author:** ${author}`,
  title ? `**Commit:** ${title}` : null,
].filter(Boolean).join('\n');

return [{
  json: {
    msg_type: 'interactive',
    card: {
      config: { wide_screen_mode: true },
      header: {
        template: colors[status] || 'blue',
        title: { tag: 'plain_text', content: `${icons[status] || 'ℹ️'} ${project} — ${name} ${status}` },
      },
      elements: [
        { tag: 'div', text: { tag: 'lark_md', content } },
        { tag: 'action', actions: [
          { tag: 'button', type: status === 'success' ? 'default' : 'danger', text: { tag: 'plain_text', content: 'Open in CircleCI' }, url },
        ] },
      ],
    },
  },
}];
